"""
H37 (S143). Cost per hour of the operators by job position.

---

Coste por hora de los operarios por puesto (Miguel Ángel: "deberíamos
tener por puesto, es decir, un gruista de grúa de gran tonelaje y el
operario normal con carné de camión"):

1. Tabla nueva `AssistanceOperatorRole` y campo `operator_role` en cada
   clase de vehículo.
2. Datos: por cada empresa con medias de coste, los puestos "Gruista
   (grúa de gran tonelaje)" y "Operario con carné de camión", los dos
   con el coste por operario que tenía (o 15,34 €/h); la clase "Grúa
   móvil" lleva el gruista y las demás el operario.
3. Se quita el coste único por operario de las medias.
4. Se recalculan los servicios valorados (si falla, se hace al guardar
   las medias).
"""

from decimal import Decimal

import django.db.models.deletion
from django.db import migrations, models

ROLE_CRANE = "Gruista (grúa de gran tonelaje)"
ROLE_OPERATOR = "Operario con carné de camión"


def create_roles(apps, schema_editor):
    """
    Create the two positions per company and assign them to the classes.

    ---

    Crea los dos puestos de cada empresa con su coste por operario y se
    los pone a sus clases de vehículo.
    """
    settings_model = apps.get_model("budgets", "AssistanceCostSettings")
    role_model = apps.get_model("budgets", "AssistanceOperatorRole")
    vehicle_model = apps.get_model("budgets", "AssistanceVehicleCost")
    for settings in settings_model.objects.all():
        cost = settings.operator_cost_per_hour or Decimal("15.34")
        roles = {}
        for order, name in enumerate((ROLE_CRANE, ROLE_OPERATOR), start=1):
            roles[name], _created = role_model.objects.get_or_create(
                company_id=settings.company_id, name=name,
                defaults={"cost_per_hour": cost, "sort_order": order},
            )
        for vehicle in vehicle_model.objects.filter(
            company_id=settings.company_id,
        ):
            vehicle.operator_role = roles[
                ROLE_CRANE if vehicle.name == "Grúa móvil" else ROLE_OPERATOR
            ]
            vehicle.save(update_fields=["operator_role"])


def recompute(apps, schema_editor):
    """
    Recompute every company with valued services.

    ---

    Recalcula los servicios valorados con el coste de cada puesto.
    """
    import logging

    settings_model = apps.get_model("budgets", "AssistanceCostSettings")
    company_ids = list(
        settings_model.objects.values_list("company_id", flat=True),
    )
    try:
        from budgets.service_evaluation import recompute_company
        from ivr_config.models import Company

        for company in Company.objects.filter(pk__in=company_ids):
            recompute_company(company)
    except Exception:  # noqa: BLE001 -- se recalcula al guardar
        logging.getLogger(__name__).exception(
            "# [VALORACION] Recalculo tras 0064 no hecho.",
        )


